1	/** Execution-time authority checks for the model-facing goal tools. */
2	
3	import type { Context } from '@deepseek-ai/cordis'
4	import type { Agent } from '@deepseek-ai/dsh-agent'
5	import type { GoalView } from '@deepseek-ai/dsh-goal'
6	import { HarnessError } from '@deepseek-ai/dsh-llm'
7	import type { SessionEvent } from '@deepseek-ai/dsh-session'
8	import type { ToolRunContext } from '@deepseek-ai/dsh-tools'
9	
10	type TurnStartEvent = Extract<SessionEvent, { type: 'turn/start' }>
11	
12	/** Current open turn plus the events accepted after its start boundary. */
13	export interface GoalToolExecution {
14	  readonly agent: Agent
15	  readonly start: TurnStartEvent
16	  readonly events: readonly SessionEvent[]
17	}
18	
19	/** Hard authority granted to one state-changing call. */
20	export type GoalToolAuthority =
21	  | { readonly kind: 'direct-human' }
22	  | { readonly kind: 'goal-round'; readonly goal: GoalView }
23	
24	/** Throw one structured tool-policy failure. */
25	function reject(message: string, code = 'GOAL_TOOL_AUTHORITY_REQUIRED'): never {
26	  throw new HarnessError(message, code)
27	}
28	
29	/** Locate the open turn enclosing a model tool call. */
30	function openTurn(agent: Agent): { start: TurnStartEvent; events: readonly SessionEvent[] } {
31	  const events = agent.session.events
32	  for (let index = events.length - 1; index >= 0; index -= 1) {
33	    const boundary = events[index]
34	    if (boundary?.type === 'turn/end') {
35	      reject('goal tools require an open model turn', 'GOAL_TOOL_DRIVER_REQUIRED')
36	    }
37	    if (boundary?.type === 'turn/start') {
38	      return { start: boundary, events: events.slice(index + 1) }
39	    }
40	  }
41	  return reject('goal tools require an open model turn', 'GOAL_TOOL_DRIVER_REQUIRED')
42	}
43	
44	/**
45	 * Resolve and authenticate the calling agent and its driver boundary.
46	 * @param ctx - Context carrying the live agent registry.
47	 * @param exec - Tool execution metadata supplied by the registry.
48	 * @returns The authenticated agent and its current turn window.
49	 */
50	export function goalToolExecution(ctx: Context, exec: ToolRunContext): GoalToolExecution {
51	  const agent = exec.agent
52	  if (agent === undefined) {
53	    return reject('goal tools require a calling agent', 'GOAL_TOOL_AGENT_REQUIRED')
54	  }
55	  if (ctx.agents.get(agent.id) !== agent || agent.status !== 'running'
56	    || ctx.agents.currentInitiator() !== agent) {
57	    return reject(
58	      'goal tools require the exact live calling agent inside its active driver',
59	      'GOAL_TOOL_DRIVER_REQUIRED',
60	    )
61	  }
62	  return { agent, ...openTurn(agent) }
63	}
64	
65	/**
66	 * Whether host-attested human input appears in the current root-agent turn.
67	 * An omitted `Agent.followup()` / `steer()` source resolves to `user`, so non-human
68	 * producers must supply their own source rather than inheriting this authority.
69	 */
70	function hasDirectHumanInput(ctx: Context, execution: GoalToolExecution): boolean {
71	  if (!ctx.agents.roots().includes(execution.agent)) return false
72	  return execution.events.some(event =>
73	    event.type === 'user/message' && event.data.source.kind === 'user')
74	}
75	
76	/** Whether this turn is the current goal's exact admitted round. */
77	function isMatchingGoalRound(execution: GoalToolExecution, goal: GoalView): boolean {
78	  return execution.events.some(event => event.type === 'user/message'
79	    && event.data.source.kind === 'goal'
80	    && event.data.source.goalId === goal.id
81	    && event.data.source.revision === goal.revision
82	    && event.data.source.round === goal.roundsStarted)
83	}
84	
85	/**
86	 * Require authority originating in a human message accepted by a runtime root.
87	 * @param ctx - Context carrying the live agent graph.
88	 * @param execution - Authenticated current tool execution.
89	 */
90	export function requireDirectHuman(ctx: Context, execution: GoalToolExecution): void {
91	  if (hasDirectHumanInput(ctx, execution)) return
92	  reject('this goal operation requires a direct human turn on a top-level agent')
93	}
94	
95	/**
96	 * Resolve completion authority from either direct human input or the exact goal round.
97	 * @param ctx - Context carrying live agents and goal state.
98	 * @param execution - Authenticated current tool execution.
99	 * @returns The direct-human or exact-goal-round authority grant.
100	 */
101	export function completionAuthority(ctx: Context, execution: GoalToolExecution): GoalToolAuthority {
102	  if (hasDirectHumanInput(ctx, execution)) return { kind: 'direct-human' }
103	  const goal = ctx.goals.get(execution.agent)
104	  if (goal !== undefined && isMatchingGoalRound(execution, goal)) {
105	    return { kind: 'goal-round', goal }
106	  }
107	  return reject('complete and blocked require a direct human turn or the current goal round')
108	}
